import{_ as e,a0 as s,w as l,s as i,I as d,x as r,a1 as a,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"10大 Linux 免費遊戲 | LCTT x X-CMD","titleTemplate":false,"description":"10大 Linux 免費遊戲 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10大 Linux 免費遊戲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10大 Linux 免費遊戲 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140731 Top 10 Free Linux Games","title":"10大 Linux 免費遊戲","tag":"201408","desc":""},"relativePath":"201408/20140731 Top 10 Free Linux Games.md","filePath":"[post].md"}'),g={name:"201408/20140731 Top 10 Free Linux Games.md"};function b(u,t,h,m,x,M){const o=s("Link");return l(),i("div",null,[t[16]||(t[16]=d("h1",{id:"_10大-linux-免費遊戲",tabindex:"-1"},[r("10大 Linux 免費遊戲 "),d("a",{class:"header-anchor",href:"#_10大-linux-免費遊戲","aria-label":"Permalink to “10大 Linux 免費遊戲”"},"​")],-1)),t[17]||(t[17]=d("p",null,"假如當你考慮從 Windows 平台遷移至 Linux 平台時，“我能在 Linux 平台上游戲嗎？”這類疑問正困擾着你，那麼對此這有一個答案就是 ———— “快去 Linux 平台吧！”。感謝開源組織一直以來堅持不懈為 Linux 操作系統開發不同類型的遊戲，還有從不缺乏好的商業遊戲，並且在 Linux 平台下游戲時的樂趣完全不亞於其他幾個平台（比如 Windows 平台）的在線數字發行平台 ———— Steam。",-1)),t[18]||(t[18]=d("p",null,"接下來我們基於流行程度、“免費遊戲”的名號以及安裝難易度向你展現今年 10 款最佳 Linux 平台下的免費遊戲。",-1)),d("p",null,[t[1]||(t[1]=r("** 注意 ** – 如果你對第一人稱射擊類（First Person Shooter，FPS）遊戲感興趣的話，請閲讀我們的另一篇文章",-1)),a(o,{href:"http://mylinuxbook.com/10-popular-fps-linux-games/"},{default:n(()=>[...t[0]||(t[0]=[r("10 款 Linux 下流行的第一人稱射擊類遊戲",-1)])]),_:1}),t[2]||(t[2]=r("。",-1))]),t[19]||(t[19]=p('<h3 id="_1-《軍團要塞-2》" tabindex="-1">1.《軍團要塞 2》 <a class="header-anchor" href="#_1-《軍團要塞-2》" aria-label="Permalink to “1.《軍團要塞 2》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/Team-fortress-2.jpg" alt=""></p><p>《軍團要塞 2》是一款由 Valve 公司開發的基於團隊的在線 FPS 類電子遊戲，是 1996 年最初 Quake 修改版的續作。這款遊戲最早於 2007 年 10 月 10 日發佈了 Windows 版與 Xbox 360 版，隨後在 2013 年 2 月 14 日作為獨立遊戲發行了 Linux 版。遊戲在 1998 年就發佈了預告，最早由 Valve 的 GoldSrc 引擎驅動，但是發行過程卻在其長達九年的開發週期中被遊戲的設計更新嚴重推遲。遊戲在 2011 年 6 月 23 日成為一款免費遊戲。</p><p>《軍團要塞 2》已經收到了許多稱讚性評論與大獎，這主要跟它充滿藝術的表現手法、遊戲的平衡性、幽默感，以及圖像風格有關。與其他遊戲，如使命召喚、半條命，採取極度真實的畫面不同，這款遊戲的設定看起來像是把卡通元素帶進了世界中。</p><p>** 遊戲介紹 **：和原版遊戲一樣，《軍團要塞 2》圍繞兩支相互對立的隊伍進行；紅隊（可信賴的拆遷隊）與藍隊（建築者聯合團體），兩隊都為了以戰鬥為基礎的主要目標相互競爭。</p><p>玩家可以選擇九種角色，分別是偵察兵、士兵、火焰兵、爆破兵、重裝兵、工程師、醫療兵、狙擊手和間諜，每一個角色都有其獨特的武器、優勢與弱點。</p><h4 id="系統需求" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求" aria-label="Permalink to “系統需求：”">​</a></h4><table><tr><td> </td><td><b>推薦配置</b></td><td><b>最低配置</b></td></tr><tr><td><b>CPU</b></td><td>奔騰4處理器或者 Athlon XP 或者更佳</td><td>奔騰4處理器或者 Athlon XP 或者更佳</td></tr><tr><td><b>CPU 速率</b></td><td>3.0 GHz 處理器</td><td>1.7 GHz</td></tr><tr><td><b>內存（RAM）</b></td><td>1 GB</td><td>512 MB</td></tr><tr><td><b>顯卡</b></td><td>支持 DirectX 9 的顯卡（NVIDIA GeForce 7900+ / ATI Radeon X1900+）</td><td>支持 DirectX 8.1 的顯卡（NVIDIA GeForce4+ / ATI Radeon 8500+）</td></tr><tr><td><b>聲卡</b></td><td>必需</td><td>必需</td></tr><tr><td><b>剩餘硬盤空間</b></td><td>5 GB</td><td>5 GB</td></tr></table><h3 id="_2-《dota-2》" tabindex="-1">2.《Dota 2》 <a class="header-anchor" href="#_2-《dota-2》" aria-label="Permalink to “2.《Dota 2》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/Dota-2.jpg" alt=""></p><p>《Dota 2》，是《Dota》的續作，是一款由 Valve 公司開發的多人在線戰術競技類（Multiplayer Online Battle Arena，MOBA）電子遊戲。《DOTA 2》發行時就完全免費，於 2013 年 7 月 9 日發行 Windows 版，於 2013 年 7 月 18 日發行 Linux 版，並且只能通過 Valve 的在線數字發行平台 Steam 進行遊戲。Dota 2 因為其令人愉悦的遊戲體驗和大幅提高的遊戲品質得到了電子遊戲評論家的熱烈稱讚。儘管 Dota 2 也因為其陡峭的學習曲線受到批評。</p><p>** 遊戲介紹 **：每一場標準的 Dota 2 比賽都是獨立的，同時由 2 支相互敵對的團體參與，天輝和夜魘，每個團隊均由 5 名玩家組成。每個團隊佔據地圖的一角作為大本營，每個團隊的大本營上均有一座被稱作“遠古神蹟”的建築存在。為了贏得遊戲，任意一方團隊必須摧毀對方的遠古神蹟。Dota 2 中有 9 種遊戲模式與 107 個英雄可供挑選。每名玩家控制一位英雄，通過升級、獲取物品、收集金幣還有擊敗敵對團隊以獲取勝利。</p><h4 id="系統需求-1" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求-1" aria-label="Permalink to “系統需求：”">​</a></h4><table><tbody><tr><td> </td><td><b>推薦配置</b></td><td><b>最低配置</b></td></tr><tr><td><strong>CPU</strong></td><td>Intel 酷睿 2 雙核處理器，2.4GHz</td><td>奔騰 4 處理器，3.0GHz</td></tr><tr><td><strong>CPU 速率</strong></td><td>2.4 GHz 處理器</td><td>3.0 GHz</td></tr><tr><td><strong>內存（RAM）</strong></td><td>1 GB</td><td>1 GB</td></tr><tr><td><strong>顯卡</strong></td><td>支持 DirectX 9 的顯卡，帶有 3.0. 優化渲染引擎模式（NVidia 7600, ATI X1600）或更優顯卡</td><td>支持 DirectX 9 的顯卡，帶有 128 MB 的 2.0. 優化渲染引擎模式（ATI X800, NVidia 6600）或更優顯卡</td></tr><tr><td><strong>聲卡</strong></td><td>必需</td><td>必需</td></tr><tr><td><strong>剩餘硬盤空間</strong></td><td>2.5 GB</td><td>2.5 GB</td></tr></tbody></table><h3 id="_3-《urban-terror》" tabindex="-1">3.《Urban Terror》 <a class="header-anchor" href="#_3-《urban-terror》" aria-label="Permalink to “3.《Urban Terror》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/UrbanTerror.jpg" alt=""></p><p>《Urban Terror》，縮寫作 UrT，是一款由 FrozenSand 開發的免費多人 FPS 電子遊戲。遊戲於 2007 年作為免費獨立遊戲發行，使用 ioquake3（某遊戲引擎項目，作為一個純淨基礎包向更多的圖像和音頻特性提供改進支持）作為引擎。</p><p>正如這款官方遊戲格言‘現實的樂趣’所述，它是一個封包很好的產品，同時安裝簡便、畫質優良、依賴需求少，並且遊戲非常平衡，這些特色使這款遊戲成為了獨一無二的、令人享受並且吸引人的遊戲。2007 年的 Mod DB 上，Urban Terror 被提名為年度 Mod 獎。</p><p>** 遊戲介紹 **：這款遊戲被標為“好萊塢戰術射擊遊戲”，具有多種遊戲的混合元素，例如：《雷神之錘 III 競技場》、《虛幻競技場》以及《反恐精英》。這款 Mod 通過一系列改變使得遊戲更加真實，比如武器和現實中的類似，具有後坐力，射擊時精準度會下降，並且當彈藥庫用完時需要重新填裝。傷害同樣現實化了，比如傷口需要包紮，腿傷或腳傷會拖慢玩家的速度。</p><h4 id="系統需求-2" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求-2" aria-label="Permalink to “系統需求：”">​</a></h4><table><tbody><tr><td> </td><td><strong>推薦配置</strong></td><td><strong>最低配置</strong></td></tr><tr><td><strong>CPU</strong></td><td>奔騰4處理器  1.2 GHz 或者更高</td><td>奔騰4處理器  1.2 GHz</td></tr><tr><td><strong>CPU 速率</strong></td><td>1.2 GHz</td><td>1.2 GHz</td></tr><tr><td><strong>內存（RAM）</strong></td><td>512 MB</td><td>256 MB</td></tr><tr><td><strong>顯卡</strong></td><td> NVidia 或者 ATI 卡，256MB 顯存或更高</td><td> NVidia 或者 ATI 卡，128MB 顯存</td></tr><tr><td><strong>硬盤</strong></td><td>50 GB 或更多</td><td>50 GB</td></tr></tbody></table><h3 id="_4-《外星人競技場-2008》" tabindex="-1">4.《外星人競技場 2008》 <a class="header-anchor" href="#_4-《外星人競技場-2008》" aria-label="Permalink to “4.《外星人競技場 2008》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/AlienArena2008.jpg" alt=""></p><p>《外星人競技場》是一款獨立 3D 第一人稱在線死亡競技射擊類電子遊戲，基於 id software 的雷神 II 與雷神 III 引擎的源代碼製作而成。這款由 COR entertainment 開發的遊戲於 2004 年 10 月發行，發行之日起即宣佈免費，並且目前為止仍沒有變更為付費遊戲的計劃。</p><p>遊戲特色包括新的粒子引擎與特效、32 位畫面、反光水面特效、光影、高分辨率畫質及皮膚、染色地圖，等等，使得《外星人競技場 2008》成為一款引人注目的遊戲。遊戲從最初的版本“紅色代碼：外星人競技場”到發行走了一段很長的路，其間更新了全部遊戲角色、將近 24 張地圖、武器模組，以及許多很重要的引擎提升與優化。</p><p>** 遊戲介紹 **：37 個等級是外星人競技場的重要特點，並且具有快速流暢的遊戲體驗以及高科技氛圍。玩家可以選擇在線與他人對戰或者與紅色代碼構建的具有多種技能等級，如火箭跳躍及機槍掃射跳躍的機器人對戰。遊戲也提供了奪旗模式（Capture The Flag，CTF）與全隊攻擊模式（All Out Assault，AOA），玩家可以通過這些模式來進行戰鬥、死亡擊球以及團隊核心戰鬥。</p><h4 id="系統需求-3" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求-3" aria-label="Permalink to “系統需求：”">​</a></h4><table><tbody><tr><td> </td><td><strong>推薦配置</strong></td><td><strong>最低配置</strong></td></tr><tr><td><strong>CPU</strong></td><td>Intel 奔騰 4 處理器，1.7 GHz 或者 AMD Athlon XP 1800</td><td>奔騰 3 處理器，800MHz</td></tr><tr><td><strong>CPU 速率</strong></td><td>1.7 GHz</td><td>800MHz (或者 1 GHz)</td></tr><tr><td><strong>內存（RAM）</strong></td><td>512 MB</td><td>256 MB</td></tr><tr><td><strong>顯卡</strong></td><td>BFG GeForce 7800 GS OC</td><td>NVIDIA GeForce 4400+ 或者 ATI Radeon 8500+ (32 MB 顯存)</td></tr><tr><td><strong>顯存</strong></td><td>64 MB</td><td>32 MB</td></tr><tr><td><strong>聲卡</strong></td><td>可兼容 DirectX</td><td>可兼容 DirectX</td></tr><tr><td><strong>DirectX</strong></td><td>9.0c</td><td>9.0c</td></tr><tr><td><strong>硬盤</strong></td><td>500 MB</td><td>500 MB</td></tr></tbody></table><h3 id="_5-《nexuiz》" tabindex="-1">5.《Nexuiz》 <a class="header-anchor" href="#_5-《nexuiz》" aria-label="Permalink to “5.《Nexuiz》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/nexuiz.jpg" alt=""></p><p>《Nexuiz》是一款由 Alientrap 開發並於 2005 年 5 月 31 日發行的第一人稱射擊死亡競技類 3D 電子遊戲，由一款名為 DarkPlaces 的修改過的雷神 1 引擎基礎上製作，其特色包括 Quake3bsp 支持，日冕，新的粒子特效，真實世界時間系統還有動態光影，改進過的菜單系統和 Md3 模組支持。遊戲需要在互聯網或者局域網環境下進行。</p><p>** 遊戲介紹 **：遊戲是死亡競技模式，同時附帶極高的速度與難以想像的武器，提供急速行走方式。除了死亡競技外還有其他幾種遊戲模式，如：團隊競技模式、獵殺模式、奪旗模式、多人變異者模式，武器選項模式也包含火箭競技場模式、instagib 模式。儘管 Nexuiz 以多人模式為主，但同時包含完整的單人戰役模式，允許一名玩家在豐富多彩的多人地圖模式的基礎上與本地機器人遊戲。</p><h4 id="系統需求-4" tabindex="-1">系統需求：#### <a class="header-anchor" href="#系統需求-4" aria-label="Permalink to “系統需求：####”">​</a></h4><table><tbody><tr><td></td><td><strong>推薦配置</strong></td><td><strong>最低配置s</strong></td></tr><tr><td><strong>CPU</strong></td><td>Intel 酷睿 2 雙核，2Ghz 或者 AMD Athlon 64 x2，2 Ghz，或者更好的處理器</td><td>奔騰 III 處理器，1 Ghz 或者 AMD Athlon</td></tr><tr><td><strong>內存（RAM）</strong></td><td>2 GB</td><td>512 MB</td></tr><tr><td><strong>顯卡</strong></td><td>NVidia 8800GT，512 Mb 顯存，ATI 3850HD，512Mb 顯存，或者更好的顯卡</td><td>GeForce 2 或者 同等性能的顯卡</td></tr><tr><td><strong>硬盤</strong></td><td>3 GB</td><td>400 MB</td></tr></tbody></table><h3 id="_6-《tremulous》" tabindex="-1">6.《Tremulous》 <a class="header-anchor" href="#_6-《tremulous》" aria-label="Permalink to “6.《Tremulous》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/Tremulous.jpg" alt=""></p><p>《Tremulous》是一款免費開源的遊戲，包含有團隊 FPS 模式與即時戰略元素。遊戲由 Dark Legion Development 在 ioquake2 遊戲引擎的基礎上開發，於 2005 年 8 月 11 日發行。儘管遊戲的起源是雷神 3 的一個 mod，但最後卻獨立出來了。</p><p>《Tremulous》榮獲了 Mod Database 舉辦的 2006 年 “年度 Mod” 頒獎典禮中的 “玩家評選的年度最佳獨立遊戲” 獎項，同時也獲得了 Planet Quake 網站玩家投票的第一個“以雷神引擎開發的基於 GPL 協議的最佳免費遊戲”。</p><p>** 遊戲介紹 **：遊戲背景可推測設定在未來，在那個時代人類與蜘蛛外形的外星人進行戰鬥。玩家可以在兩個僅有的種族——人類與外星人——中選擇自己的種族，每個種族的玩家都可以像即時戰略遊戲一樣在遊戲中進行建築。其中最重要的建築是重生點，重生點允許死亡的隊友重新加入遊戲。</p><h4 id="系統需求-5" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求-5" aria-label="Permalink to “系統需求：”">​</a></h4><table><tbody><tr><td> </td><td><strong>推薦配置</strong></td><td><strong>最低配置</strong></td></tr><tr><td><strong>CPU</strong></td><td>奔騰 4 處理器，3.46GHz 或者 Athlon 64 3800+</td><td>奔騰 4 處理器，1.8GHz 或者 Athlon XP 1700+</td></tr><tr><td><strong>內存（RAM）</strong></td><td>2 GB</td><td>256 MB</td></tr><tr><td><strong>顯卡</strong></td><td>Nvidia GeForce GT 120 , AMD Radeon HD 4550</td><td>Nvidia GeForce 210 , AMD Radeon X600 系列s</td></tr><tr><td><strong>DirectX 版本</strong></td><td>DX 9.0c</td><td>DX 9.0c</td></tr><tr><td><strong>硬盤空間</strong></td><td>4 GB</td><td>125 MB</td></tr></tbody></table><h3 id="_7-《warsow》" tabindex="-1">7.《Warsow》 <a class="header-anchor" href="#_7-《warsow》" aria-label="Permalink to “7.《Warsow》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/warsow.jpg" alt=""></p><p>《Warsow》是一款在線的第一人稱射擊類（FPS）電子遊戲，其創作靈感來源於 90 年代末期以及 20 世紀初期的快速步行射擊。Warsow 的代碼庫是免費開源的軟件，遵循 GPL 協議，在雷神 II 引擎的改進版 Qfusion 的基礎上開發而來。Warsow 吸引人的地方在於其獨一無二的體驗，這些體驗來自於其開發團隊努力追求着去開發一款有趣、快速的動作類遊戲，並且致力於速度、花樣跳躍與動作的藝術。這款遊戲在卡通風格中運用了細節陰影圖像技術，使得遊戲主題呈現出賽博朋克的風格。</p><p>** 遊戲介紹 **：這款快速步行 3D 單人射擊遊戲將主要目標集中於移動和花樣跳躍，其中許多花樣來自於雷神系列，包括圓周跳躍、兔子跳躍、二段跳、斜坡滑行，以及火箭跳躍。除了這些花樣，《Warsow》也允許玩家飛奔、閃避或者沿牆跳躍，這個動作很有可能是來源於《Urban Terror》。</p><h3 id="系統需求-6" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求-6" aria-label="Permalink to “系統需求：”">​</a></h3><table><tbody><tr><td></td><td><strong>最低配置</strong></td></tr><tr><td><strong>CPU</strong></td><td>奔騰 II 處理器，300 Mhz 或者更好的處理器</td></tr><tr><td><strong>內存（RAM）</strong></td><td>64 MB</td></tr><tr><td><strong>顯卡</strong></td><td>16 MB 顯存（Riva TNT 或者更好的顯卡）</td></tr><tr><td><strong>硬盤</strong></td><td>400 MB</td></tr></tbody></table><p>** 注意 ** – 這款遊戲的推薦配置可能不準確。下面是我們從一些論壇的討論中得到的結果：</p><ul><li>CPU – Intel 奔騰 4 處理器 (3.00 GHz)</li><li>內存（RAM） - 512 MB</li><li>顯卡 - 256 MB (nVidia GeForce 5500 FX)</li><li>硬盤 - 2 GB</li></ul><h3 id="_8-《開放競技場》-oa" tabindex="-1">8.《開放競技場》（OA）### <a class="header-anchor" href="#_8-《開放競技場》-oa" aria-label="Permalink to “8.《開放競技場》（OA）###”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/open-arena.jpg" alt=""></p><p>《開放競技場》是一款開源的多人 FPS 類遊戲，基於由 id tech 3 引擎 fork 的 ioquake3 開發而來。遊戲由 OpenArena 團隊開發，並且遵守 GPLv2協議。遊戲官方網站的下載版本包括 GNU/Linux，Microsoft Windows 以及 Mac OS X 操作系統的對應版，同樣支持諸如 Debian、Gentoo、Fedora、Arch、Mandriva 還有 Ubuntu 等 Linux 發行版。開放競技場是一款可以離線或者在線進行的免費遊戲，玩家也可以自己架設局域網或者 Internet 服務器。</p><p>** 遊戲介紹 **：《開放競技場》幾乎和《雷神 III 競技場》一樣：通過殺敵得分獲得遊戲勝利，在不同的場景下可以使用一系列為平衡遊戲所設計的武器。每場競賽都有其獨特的“競技場”，地圖上玩家們互相殘殺；遊戲包含多種遊戲類型：死亡競賽、錦標賽、團隊死亡競賽，還有奪旗模式。由於暴力以及成人因素，這款遊戲由於其暴力程度並不適於 17 歲以下的孩子。</p><h4 id="系統需求-7" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求-7" aria-label="Permalink to “系統需求：”">​</a></h4><table><tbody><tr><td></td><td><strong>推薦配置</strong></td><td><strong>最低配置</strong></td></tr><tr><td><strong>CPU</strong></td><td>奔騰 III 處理器，700MHz / AMD Athlon XP 2800+</td><td>奔騰 II 處理子，233MHz / AMD K6-2 300MHz 或者同等性能的處理器</td></tr><tr><td><strong>內存（RAM）</strong></td><td>256 MB</td><td>64 MB</td></tr><tr><td><strong>顯卡</strong></td><td>Geforce 4 Ti 4400</td><td>16 MB（附帶 OpenGL 加速）</td></tr><tr><td><strong>硬盤空間</strong></td><td>270 MB</td><td>50 MB</td></tr></tbody></table><h3 id="_9-《freecol》" tabindex="-1">9.《Freecol》 <a class="header-anchor" href="#_9-《freecol》" aria-label="Permalink to “9.《Freecol》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/Freecol.jpg" alt=""></p><p>《FreeCol》是一款免費開源的回合制策略類電子遊戲，是古老遊戲《殖民帝國》的仿製遊戲，並且和《文明》非常相似。遊戲最早於 2003 年 1 月 2 日發行，但是遊戲的穩定版在 17 個 月前的 2013 年 1 月 7 日才剛剛發行。從遊戲內容與過程來説，穩定版保持了最初版的樣子，但是其遊戲圖像經過了重新設計。</p><p>** 遊戲介紹 **：遊戲時的目標是開拓新的殖民世界。遊戲設定開始於 1492 年，初始有幾艘船以及一些殖民者，玩家通過殖民者進行建築並殖民擴張，同時與其他歐洲殖民者進行對抗。殖民者的擴張在歐洲王國的幫助下進行直到不再需要任何來自歐洲的協助，這表明殖民者已經獨立並且不再需要任何來自外部的協助，接着宣佈從王國獨立出來。如果殖民者可以抵擋住來自王國的攻擊，那麼遊戲就獲勝了。</p><h4 id="系統需求-8" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求-8" aria-label="Permalink to “系統需求：”">​</a></h4><table><tbody><tr><td></td><td><strong>推薦配置</strong></td><td><strong>最低配置</strong></td></tr><tr><td><strong>CPU</strong></td><td>Intel(R) 酷睿(TM)2 雙核 CPU P8700，2.53 GHz</td><td>奔騰 3 處理器，1GHz</td></tr><tr><td><strong>內存（RAM）</strong></td><td>512 MB</td><td>256 MB</td></tr><tr><td><strong>Java 版本</strong></td><td>JRE 7(Java Runtime Environment 7)</td><td>JREt 5 (or JRE 6)</td></tr><tr><td><strong>屏幕分辨率</strong></td><td>1024 X 768</td><td>1024 X 768</td></tr></tbody></table><h3 id="_10-《急速-tux-競賽》" tabindex="-1">10.《急速 Tux 競賽》 <a class="header-anchor" href="#_10-《急速-tux-競賽》" aria-label="Permalink to “10.《急速 Tux 競賽》”">​</a></h3><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/07/Extreme_Tux_Racer.jpg" alt=""></p><p>《急速 Tux 競賽》，原名《Tux 競賽》，是一款免費的 3D 電腦遊戲軟件，允許玩家使用 Linux 吉祥物，Tux 企鵝進行遊戲。遊戲於 2000 年 10 月 2 日，由在加拿大安大略省滑鐵盧大學就讀的在校生 Jasmin Patry 發行。遊戲是一款非常新穎的 Linux 遊戲，是非常有趣簡單的競速比賽，沒有任何複雜或者暴力的元素，這使得遊戲適合於任何年齡段的玩家。</p><p>** 遊戲介紹 **：遊戲裏，Tux 沿着各種不同的賽道在陡峭的被冰雪覆蓋的山上滑行，以衝擊最短時間與最高分數為目標。可以通過在賽道上衝刺滑行時收集鯡魚來提高分數。在雪地滑行時活動將更加靈活，在冰上滑行能加快 Tux 的速度，在岩石上滑行則會拖慢 Tux 的速度。</p><h3 id="系統需求-9" tabindex="-1">系統需求： <a class="header-anchor" href="#系統需求-9" aria-label="Permalink to “系統需求：”">​</a></h3><table><tbody><tr><td></td><td><strong>推薦配置</strong></td><td><strong>最低配置</strong></td></tr><tr><td><strong>CPU</strong></td><td>400 MHz 的處理器，或者更好的處理器</td><td>奔騰處理器，200MMX</td></tr><tr><td><strong>內存（RAM）</strong></td><td>128 MB</td><td>64 MB</td></tr><tr><td><strong>顯卡</strong></td><td>TNT2/Voodoo3-class 3D 顯卡，或者更好的顯卡</td><td>3D 顯卡，附帶完全 OpenGL 支持</td></tr><tr><td><strong>聲卡</strong></td><td>16-bit</td><td>16-bit</td></tr><tr><td><strong>硬盤</strong></td><td>20 MB</td><td>20 MB</td></tr></tbody></table><p>有話要説？在下面發表你的評論吧。</p><hr>',69)),d("p",null,[t[4]||(t[4]=r("via: ",-1)),a(o,{href:"http://mylinuxbook.com/top-10-free-linux-games/"},{default:n(()=>[...t[3]||(t[3]=[r("http://mylinuxbook.com/top-10-free-linux-games/",-1)])]),_:1})]),d("p",null,[t[8]||(t[8]=r("作者：",-1)),a(o,{href:"http://mylinuxbook.com/author/himanshuc/"},{default:n(()=>[...t[5]||(t[5]=[r("Himanshu Arora",-1)])]),_:1}),t[9]||(t[9]=r(" 譯者：",-1)),a(o,{href:"https://github.com/SteveArcher"},{default:n(()=>[...t[6]||(t[6]=[r("SteveArcher",-1)])]),_:1}),t[10]||(t[10]=r(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[7]||(t[7]=[r(" wxy",-1)])]),_:1})]),d("p",null,[t[13]||(t[13]=r("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[11]||(t[11]=[r("LCTT",-1)])]),_:1}),t[14]||(t[14]=r(" 原創翻譯，",-1)),a(o,{href:"http://linux.cn/"},{default:n(()=>[...t[12]||(t[12]=[r("Linux中國",-1)])]),_:1}),t[15]||(t[15]=r(" 榮譽推出",-1))])])}const G=e(g,[["render",b]]);export{P as __pageData,G as default};
